166	    /**
167	     * Run the simulation from its current state for a single step.
168	     * Iterate over the whole field updating the state of each actor.
169	     */
170	    public void simulateOneStep()
171	    {
172	        step++;
173	        
174	        // Update the weather:
175	        if (TimeSystem.hasDayChanged())
176	        {
177	            WeatherSystem.changeToNextDay();
178	            
179	        }
180	
181	        // Provide space for newborn actors:
182	        List<Actor> newActors = new ArrayList<>();
183	        
184	        // Let all actors act:
185	        for (Iterator<Actor> it = actors.iterator(); it.hasNext(); )
186	        {
187	            Actor actor = it.next();
188	            
189	            actor.act(newActors);
190	            
191	            if(!actor.getIsAlive()) it.remove();
192	        }
193	               
194	        // Add the newly born actors to the main list:
195	        actors.addAll(newActors);
196	
197	        view.showStatus(step, field);
198	    }
