223	    /**
224	     * Randomly populate the field with actors.
225	     */
226	    private void populate()
227	    {
228	        Random rand = Randomizer.getRandom();
229	        field.clear();
230	        
231	        for (int row = 0; row < field.getDepth(); row++)
232	        {
233	            for (int col = 0; col < field.getWidth(); col++)
234	            {
235	                Location location = new Location(row, col);
236	                Actor actor = createInitialActor(location, rand);
237	
238	                if (actor != null) actors.add(actor);
239	            }
240	        }
241	    }
