243	    /**
244	     * Create the initial actor for a field location.
245	     * The configured probabilities are applied in order, while using a single
246	     * random draw to preserve the existing overall distribution.
247	     *
248	     * @param location The field location being populated.
249	     * @param random   The shared random number generator.
250	     * @return A new actor for the location, or null if it remains empty.
251	     */
252	    private Actor createInitialActor(Location location, Random random)
253	    {
254	        double selection = random.nextDouble();
255	        double cumulativeProbability = 0.0;
256	        double remainingProbability = 1.0;
257	
258	        for (SpeciesDefinition definition : SPECIES_DEFINITIONS)
259	        {
260	            double effectiveProbability = remainingProbability * definition.creationProbability;
261	            cumulativeProbability += effectiveProbability;
262	
263	            if (selection <= cumulativeProbability)
264	            {
265	                return definition.factory.create(field, location);
266	            }
267	
268	            remainingProbability -= effectiveProbability;
269	        }
270	
271	        return null;
272	    }
